#include <iostream>
#include <string>
#include <vector>
class ResourceHolder {
public:
    ResourceHolder() : ptr(new std::string("Hello")) {}
    ~ResourceHolder() { delete ptr; }
    ResourceHolder(const ResourceHolder& other) : ptr(new std::string(*other.ptr)) {}
    ResourceHolder& operator=(const ResourceHolder& other) {
        if (this != &other) {
            delete ptr;
            ptr = new std::string(*other.ptr);
        }
        return *this;
    }
    // Add move constructor and move assignment operator here for improved performance
    std::string get_string() const {return *ptr;}
private:
    std::string* ptr;
};
int main() {
  ResourceHolder rh1;
  ResourceHolder rh2 = rh1; // Uses copy constructor
  std::cout << rh2.get_string() << std::endl;
  return 0;
}
